      const k = t / spin;
      const head = 2.5 * k * k * n;
      const tail = 2.0 + 7.0 * k;
      const out = Array.from({ length: n }, (_, i) => scaled(col, Math.max(0, 1 - mod(head - i, n) / tail) * (0.4 + 0.6 * k)));
